const cnDay = (d) => new Intl.DateTimeFormat('sv-SE', { timeZone: 'Asia/Shanghai', year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
const dayDiff = (a, b) => {
  const p = (s) => Date.UTC(+s.slice(0, 4), +s.slice(5, 7) - 1, +s.slice(8, 10));
  return Math.round((p(a) - p(b)) / 86400000);
};

const today = cnDay(new Date());
const dLeft = dayDiff(EXAM_DATE, today);
const dayIdx = Math.max(1, dayDiff(today, START_DATE) + 1);
const weekday = new Date().getDay(); // 0=周日

