function notiDecode(s) {
  return String(s)
    .replace(/<[^>]+>/g, '')
    .replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#\d+;/g, ' ')
    .replace(/\s+/g, ' ').trim();
}

function notiDate(url, title) {
  const m = String(url).match(/(20\d{2})(\d{2})(\d{2})/);
  if (m) return `${m[1]}-${m[2]}-${m[3]}`;
  const t = String(title || '').match(/(20\d{2})[-\/年.](\d{1,2})[-\/月.](\d{1,2})/);
  if (t) return `${t[1]}-${String(t[2]).padStart(2, '0')}-${String(t[3]).padStart(2, '0')}`;
  return null;
}

function notiParse(html, pageUrl, 来源, 从) {
  let h = html;
  if (从) {
    const i = html.indexOf(从);
    if (i > 0) h = html.slice(i, i + 20000);
  }
  const out = [];
  const re = /<a\b([^>]*)>([\s\S]*?)<\/a>/gi;
  let m;
  while ((m = re.exec(h)) !== null) {
    const attrs = m[1];
    const hrefM = attrs.match(/href\s*=\s*"([^"]+)"/i) || attrs.match(/href\s*=\s*'([^']+)'/i);
    if (!hrefM) continue;
    const href = hrefM[1].trim();
    if (!href || href.startsWith('#') || href.startsWith('javascript')) continue;
    const titleAttr = (attrs.match(/title\s*=\s*"([^"]*)"/i) || [])[1];
    const 标题 = notiDecode(titleAttr || m[2]);
    if (!标题 || 标题.length < 6 || 标题.length > 120) continue;
    if (/^(查看更多|更多|下一页|上一页|首页|尾页|登录|注册|返回)/.test(标题)) continue;
    if (/^\d{4}[-\/]\d{1,2}[-\/]\d{1,2}$/.test(标题)) continue;
    let abs;
    try { abs = new URL(href, pageUrl).href; } catch (e) { continue; }
    if (!/\.(html?|shtml)(\?|$)/i.test(abs)) continue;
    const 日期 = notiDate(abs, 标题);
    if (!日期) continue;
    out.push({ 标题, 链接: abs, 来源, 日期 });
  }
  const seen = new Set();
  return out
    .filter((x) => (seen.has(x.链接) ? false : seen.add(x.链接)))
    .sort((a, b) => (a.日期 < b.日期 ? 1 : -1))
    .slice(0, 20);
}

